  function renderPage(){clearInterval(processTimer);const root=$('page');clear(root);if(['Files','Terminal','Git','Docker'].includes(active))pageHead(root,active,'Project: '+(project?.name||t('No project selected')));if(['Files','Terminal','Git','Docker'].includes(active)&&!project){root.append(empty('Open a project to get started.'));return;}const routes={Home:home,Projects:projectsPage,Agents:agents,Connectors:connectors,'MCP Servers':mcp,Browser:browser,Files:files,Terminal:terminal,Git:git,Docker:docker,Tasks:tasksPage,Monitoring:monitoring,Settings:settings};if(active!=='Home'){const bar=node('nav',undefined,'context-tools');bar.setAttribute('aria-label',t('Workspace tools'));for(const label of ['Projects','MCP Servers','Browser','Files','Terminal','Git','Docker','Tasks','Monitoring','Settings']){const b=button(label,()=>navigate(label));b.id='tool-'+label.toLowerCase().replaceAll(' ','-');if(active===label)b.setAttribute('aria-current','page');bar.append(b);}root.prepend(bar);}if(active==='Permissions'){setting='Permissions';settings(root);}else routes[active](root);syncI18n();}
